diff --git a/test/conformance/serial/ptp.go b/test/conformance/serial/ptp.go
index a528935c..406a9794 100644
--- a/test/conformance/serial/ptp.go
+++ b/test/conformance/serial/ptp.go
@@ -1119,6 +1119,9 @@ var _ = Describe("["+strings.ToLower(DesiredMode.String())+"-serial]", Serial, f
 			// The test does an in-place edit to set gmCapable=1 + clockClass=248, then
 			// restores the original config via DeferCleanup.
 			It("Verify clockClass when locking PTP source on single NIC boundary clock", func() {
+				if !ptphelper.IsPTPOperatorVersionAtLeast("4.16") {
+					Skip("T-BC clock class verification requires PTP Operator 4.16+")
+				}
 				if fullConfig.PtpModeDiscovered != testconfig.BoundaryClock {
 					Skip("Test only valid for single NIC Boundary Clock")
 				}
@@ -1169,6 +1172,9 @@ var _ = Describe("["+strings.ToLower(DesiredMode.String())+"-serial]", Serial, f
 			})

 			It("Verify clockClass when locking PTP source on dual NIC boundary clock", func() {
+				if !ptphelper.IsPTPOperatorVersionAtLeast("4.16") {
+					Skip("T-BC clock class verification requires PTP Operator 4.16+")
+				}
 				if fullConfig.PtpModeDiscovered != testconfig.DualNICBoundaryClock &&
 					fullConfig.PtpModeDiscovered != testconfig.DualNICBoundaryClockHA {
 					Skip("Test only valid for dual NIC Boundary Clock configurations")
@@ -2084,6 +2090,9 @@ var _ = Describe("["+strings.ToLower(DesiredMode.String())+"-serial]", Serial, f
 			})

 			It("BC clock class recovers to Locked after upstream link outage", func() {
+				if !ptphelper.IsPTPOperatorVersionAtLeast("4.16") {
+					Skip("T-BC clock class recovery requires PTP Operator 4.16+")
+				}
 				if fullConfig.PtpModeDiscovered == testconfig.TelcoGrandMasterClock {
 					Skip("test not valid for WPC GM config")
 				}
diff --git a/test/pkg/ptptesthelper/ptptesthelper.go b/test/pkg/ptptesthelper/ptptesthelper.go
index a0d28183..5c7d64d4 100644
--- a/test/pkg/ptptesthelper/ptptesthelper.go
+++ b/test/pkg/ptptesthelper/ptptesthelper.go
@@ -439,6 +439,7 @@ func (p *PortEngine) TurnAllPortsDown(skippedInterfaces map[string]bool) error {
 			logrus.Infof("Skipping interface: %s (in skip list)", port)
 			continue
 		}
+		p.nmSetManaged(port, false)
 		stdout, stderr, err := pods.ExecCommand(client.Client, true, p.ClockPod, pkg.RecoveryNetworkOutageDaemonSetContainerName,
 			[]string{"ip", "link", "set", port, "down"})
 		if err != nil {
@@ -461,6 +462,7 @@ func (p *PortEngine) TurnAllPortsUp() error {
 		if err != nil {
 			return err
 		}
+		p.nmSetManaged(port, true)

 		logrus.Infof("Turning interface: %s in pod %s up, stdout: %s, stderr: %s", port, p.ClockPod.Name, stdout.String(), stderr.String())
 	}

